/**
 * Signals in message DRIVE1_CMD.
 *
 * Command to DRIVE1 (node 4), 50 Hz, master only. MODE: 0 coast, 1 brake, 2 velocity, 3 open-loop duty (TARGET_A/B then read as 0.01% duty). Applied at the next SYNC.
 *
 * All signal values are as on the CAN bus.
 */
struct rover_drive1_cmd_t {
    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t seq;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t sender_host;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t term_low;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t mode;

    /**
     * Range: -32768..32767 (-327.68..327.67 rad/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t target_a;

    /**
     * Range: -32768..32767 (-327.68..327.67 rad/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t target_b;

    /**
     * Range: 0..65535 (0..655.35 rad/s^2)
     * Scale: 0.01
     * Offset: 0
     */
    uint16_t accel_limit;
};

/**
 * Signals in message DRIVE1_FB_A.
 *
 * DRIVE1 fast feedback: state and fault flags, measured speed and current. 50 Hz. STATE: 0 BOOT, 1 DISARMED, 2 ARMED, 3 FAULT, 4 ESTOP, 5 BOOTLOADER. FAULT_FLAGS bit0 overcurrent A, 1 overcurrent B, 2 over-temp, 3 under-voltage, 4 encoder A fault, 5 encoder B fault, 6 command timeout, 7 E-stop latched.
 *
 * All signal values are as on the CAN bus.
 */
struct rover_drive1_fb_a_t {
    /**
     * Range: 0..5 (0..5 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t state;

    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t fault_flags;

    /**
     * Range: -32768..32767 (-327.68..327.67 rad/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t speed_a;

    /**
     * Range: -32768..32767 (-327.68..327.67 rad/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t speed_b;

    /**
     * Range: 0..255 (0..51 A)
     * Scale: 0.2
     * Offset: 0
     */
    uint8_t current_a;

    /**
     * Range: 0..255 (0..51 A)
     * Scale: 0.2
     * Offset: 0
     */
    uint8_t current_b;
};

/**
 * Signals in message DRIVE1_FB_B.
 *
 * DRIVE1 raw encoder counts, 50 Hz. Counts per revolution is a node parameter.
 *
 * All signal values are as on the CAN bus.
 */
struct rover_drive1_fb_b_t {
    /**
     * Range: -2147483648..2147483647 (-2147483648..2147483647 counts)
     * Scale: 1
     * Offset: 0
     */
    int32_t encoder_a;

    /**
     * Range: -2147483648..2147483647 (-2147483648..2147483647 counts)
     * Scale: 1
     * Offset: 0
     */
    int32_t encoder_b;
};

/**
 * Signals in message DRIVE1_TELEM_0.
 *
 * DRIVE1 slow telemetry page 0. 10 Hz (1 Hz at debug level 0).
 *
 * All signal values are as on the CAN bus.
 */
