    /**
     * Range: -128..127 (-128..127 degC)
     * Scale: 1
     * Offset: 0
     */
    int8_t temp_driver_b;

    /**
     * Range: -128..127 (-128..127 degC)
     * Scale: 1
     * Offset: 0
     */
